<?php namespace App\Controllers; use Vedairo\Http\Request;use Vedairo\Http\Response;use App\Models\User;use Vedairo\Validation\Validator; class UserController {public function index(Request $r):string{$users=User::all();ob_start();include base_path('resources/views/users/index.php');return (string) ob_get_clean();}public function store(Request $r):never{$v=new Validator($r->input(),['name'=>'required|min:2|max:100','email'=>'required|email','password'=>'required|min:6']);if(!$v->validate()){Response::json(['success'=>false,'errors'=>$v->errors()],422);}$id=User::create(['name'=>$r->input('name'),'email'=>$r->input('email'),'password'=>password_hash($r->input('password'),PASSWORD_DEFAULT),'role'=>'user','created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);redirect('/users');}public function apiIndex(Request $r):never{Response::json(['success'=>true,'data'=>User::query()->select('id,name,email,role,created_at')->get()]);}}
